import math

def phase_margin(a0, poles_hz, beta):
    """Phase margin in degrees of the loop T(f) = beta * a0 / prod(1 + j f / p)."""
    def mag(f):
        t = beta * a0
        for p in poles_hz:
            t /= abs(1 + 1j * f / p)
        return t
    lo, hi = 1e-6, 1e15                 # |T| falls monotonically: bisect for |T| = 1 on a log axis
    for _ in range(200):
        mid = math.sqrt(lo * hi)
        if mag(mid) > 1:
            lo = mid
        else:
            hi = mid
    phase = -sum(math.degrees(math.atan(mid / p)) for p in poles_hz)
    return 180 + phase

exercises.solution:
Bisect for the crossover on a log axis, then sum the pole lags there:

```python
import math

def phase_margin(a0, poles_hz, beta):
    def mag(f):
        t = beta * a0
        for p in poles_hz:
            t /= abs(1 + 1j * f / p)
        return t
    lo, hi = 1e-6, 1e15
    for _ in range(200):
        mid = math.sqrt(lo * hi)
        if mag(mid) > 1:
            lo = mid
        else:
            hi = mid
    phase = -sum(math.degrees(math.atan(mid / p)) for p in poles_hz)
    return 180 + phase
```

Summing `atan` terms instead of taking the angle of the complex product avoids the wrap-around at ±180°, so an unstable follower correctly returns −33.7° rather than a misleading +326°. The results: 54.9° (gain 100), 3.5° (gain 10), −33.7° (follower), 83.8° when compensated, 18.0° for a two-pole loop with poles at 1 kHz and 1 MHz and $A_0 = 10^4$, and exactly 90° for any single-pole loop.
